/* pkgKDA, ASKs 301 to 303 (W3 6439): a judge's ANSWER CHECK line graded MEETS is tested against three doctrine rules on the answer it grades. 301 DG-57: an answer that leans on "the same word" (or "the Hebrew/Greek word", "the text's own use of", "the word used") cites a verse whose original words do not carry that word's Strong's number. 302 DG-57 Isaiah 7:16: an answer that grants the 7:16 bound and carries the sign past it with Matthew 1:22 or 1:23 alone. 303 Sight 266: an answer on Matthew 1:18-25 that gives a reason of origin or makes the child not Joseph's. Each is a K-AG item (TRIAL): the line must be written again graded UNPROVEN or MISSES. */ function kdaCtx2024(){if(kdaCtx2024.c)return kdaCtx2024.c;let F=null,W=null;try{const g=(typeof $==='function')?$:null;if(g){try{if(g('Regrade Load').isExecuted)F=(g('Regrade Load').first().json||{}).f||null;}catch(e){}if(!F){try{F=g('Final Output').first().json;}catch(e){F=null;}}try{if(g('L2 Words').isExecuted){W={};for(const it of g('L2 Words').all()){const r=it&&it.json;if(!r||!r.book||!r.strongs_number)continue;const k=r.book+'|'+r.chapter+'|'+r.verse;(W[k]=W[k]||new Set()).add(String(r.strongs_number).replace(/^([HG])0*/i,(m,a)=>a.toUpperCase()));}}}catch(e){W=null;}}}catch(e){}kdaCtx2024.c={F,W};return kdaCtx2024.c;}
 function kdaRefs2024(s){const out=[];let bk=null;const re=/\b((?:[1-3]\s)?[A-Z][a-z]+(?:\s+of\s+[A-Z][a-z]+)?)\s+(\d{1,3}):(\d{1,3})|(?<![\w:])(\d{1,3}):(\d{1,3})(?![\d:])/g;let m;while((m=re.exec(s))){if(m[1]){bk=m[1].replace(/^Psalm$/,'Psalms');out.push(bk+' '+m[2]+':'+m[3]);}else if(bk)out.push(bk+' '+m[4]+':'+m[5]);}return out;}
 function kdaAnswer2024(r,F){const k=(String(r.rk||'').match(/\b([CD]R[1-4])\b/i)||[])[1];const M={CR1:'cr1',DR1:'gr1',CR2:'cr2',DR2:'gr2',CR3:'cr3',DR3:'dr3',CR4:'cr4',DR4:'dr4'};const T=k&&F?String(F[M[k.toUpperCase()]]||''):'';const v=String(r.verse||'').replace(/\s+/g,' ').trim();const vk=v.match(/^((?:[1-3]\s)?[A-Za-z]+(?:\s+of\s+[A-Za-z]+)?)\s+(\d{1,3}):(\d{1,3})/);
  const out=[];if(T&&vk){const re=new RegExp('^\\s*(?:[-*\\u2022]|\\d+[.)])\\s*\\**\\s*'+vk[1].replace(/\s+/g,'\\s+')+'\\s+'+vk[2]+':'+vk[3]+'(?!\\d)','i');for(const l of T.split('\n'))if(re.test(l))out.push(l.trim());}
  if(out.length)return {text:out.join('\n'),from:k.toUpperCase()};const a=String(r.line||'').match(/--\s*ANSWER\s*:\s*([\s\S]*?)\s*--\s*(?:MEETS|MISSES|FAILS|UNPROVEN)\b/i);return {text:a?a[1]:'',from:'the judge\'s quote'};}
 function kdaHit2024(r,A,W){const s0=String(A||'').replace(/\\+/g,'').replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/[*_`]+/g,'');const s=s0.replace(/"[^"\n]*"/g,' "" ');const neg=i=>/\b(?:denies|refutes|rejects|against|never\s+says|does\s+not\s+say)\b[^.;]*$/i.test(s.slice(Math.max(0,i-40),i));const v=String(r.verse||'');
  if(/^\s*Matthew\s+1:(?:1[89]|2[0-5])\b/i.test(v)){const m=s.match(/\banswers?\s+(?:it\s+|him\s+)?with\s+(?:the\s+child'?s\s+)?origin\b|\ba\s+reason\s+of\s+origin\b|\bnot\s+that\s+origin\b|\bnot\s+the\s+father\b|\b(?:the\s+)?child\s+(?:was|is)\s+not\s+(?:his|Joseph'?s)\b|\bsuspected\s+adultery\b|\bangel\b[^.]{0,100}\bnot\s+(?:his|Joseph'?s)\b/i);
   if(m&&!neg(m.index))return {doc:'Sight 266 (DG-8)',why:'the answer it grades reads "'+m[0]+'"; Matthew 1:19 joins "just" and "not willing" and gives no reason of origin, and the child is Joseph\'s (Sight 266, DG-8)',need:'MISSES or UNPROVEN'};}
  {const m=s.match(/\bnear\s+(?:deliverance|fulfil+ment)\b|\bbounded\s+in\s+Isaiah'?s\s+(?:own\s+)?day\b|\ba\s+sign\s+(?:to|for)\s+Ahaz\b/i);if(m&&!neg(m.index)&&/\bIsaiah\s+7:1[46]\b|^\s*Isaiah\s+[78]:/i.test(v+' '+s)){const rf=kdaRefs2024(s0);const lift=rf.filter(x=>!/^Isaiah\s+[78]:/.test(x)&&!/^Matthew\s+1:2[23]$/.test(x));if(rf.some(x=>/^Matthew\s+1:2[23]$/.test(x))&&!lift.length)return {doc:'DG-57 (Isaiah 7:16)',why:'the answer it grades grants the 7:16 bound ("'+m[0]+'") and carries the sign past it with Matthew 1:22 or 1:23 alone; it cites no text that lifts the bound',need:'UNPROVEN'};}}
  if(W){const ss=s0.split(/(?<=[.;])\s+/);const num=((s0.match(/\b([HG])0*(\d{1,5})\b/)||[]).slice(1).join(''))||((String(r.line||'').match(/\b([HG])0*(\d{1,5})\b/)||[]).slice(1).join(''));
   if(num){const self=kdaRefs2024(v)[0]||'';for(const t of ss){if(!/\bthe\s+same\s+word\b|\bthe\s+(?:Hebrew|Greek)\s+word\b|\bthe\s+text'?s\s+own\s+use\s+of\b|\bthe\s+word\s+used\b/i.test(t.replace(/"[^"\n]*"/g,' ')))continue;
    for(const ref of kdaRefs2024(t)){if(ref===self)continue;const mm=ref.match(/^(.+)\s(\d+):(\d+)$/);const set=W[mm[1]+'|'+mm[2]+'|'+mm[3]];if(!set||set.has(num))continue;return {doc:'DG-57 (Strong\'s mismatch)',why:'the answer it grades leans on the same word, and cites '+ref+', which does not carry '+num+' in the original-words table',need:'UNPROVEN'};}}}}
  return null;}
 function kdaPush2024(r,items,marks){if(r.grade!=='MEETS'||r.none)return;const C=kdaCtx2024();const A=kdaAnswer2024(r,C.F);if(!A.text)return;const h=kdaHit2024(r,A.text,C.W);if(!h)return;
  const link='ANSWER CHECK '+r.verse+(r.rk?' ('+r.rk.replace(/\s*[;,]\s*/g,'; ')+')':'');if(items.some(x=>x.link===link&&x.doc))return;
  items.push({rule:'K-AG',side:'JUDGE',link,verse:r.verse,rk:r.rk,grade:r.grade,none:false,doc:h.doc,line:'['+link+'] your ANSWER CHECK line grades MEETS, but '+h.why+' (read from '+A.from+'). An answer on that ground cannot MEET the press ('+h.doc+'; pkgKDA). Write the line again graded '+h.need+'. NOT HELD does not cure this item. Your line: '+r.line.slice(0,600)});
  marks.push('[AUDIT v41: ANSWER CHECK DOCTRINE (K-AG; '+h.doc+'; TRIAL; pkgKDA) -- '+link+' -- '+h.why.replace(/[\[\]]/g,'').slice(0,300)+']');}
